package me.eren.blocktrackerapi.api;

import me.eren.blocktrackerapi.tracker.WorldTracker;
import org.bukkit.Location;
import org.bukkit.World;
import org.bukkit.block.Block;

/**
 * View and control of which blocks are natural. A natural block (bit {@code 0}) was generated by
 * the world; a non-natural block (bit {@code 1}) was placed by a player.
 *
 * <p>All methods must be called from the server main thread.
 */
public interface BlockTracker {

	boolean isNatural(World world, int x, int y, int z);

	boolean isNatural(Block block);

	boolean isNatural(Location location);

	/**
	 * Sets whether a block is natural. Pass {@code true} for natural (world-generated) or
	 * {@code false} for not natural (player-placed). The change is persisted when the chunk
	 * unloads; the chunk must currently be loaded.
	 */
	void setNatural(World world, int x, int y, int z, boolean natural);

	void setNatural(Block block, boolean natural);

	void setNatural(Location location, boolean natural);

	WorldTracker tracker(World world);

}
